D["持仓分析_分析"] = ("这是一份清一色银行股的组合，底层逻辑是" + H(CYAN, "高股息、低估值与类债现金流") + "构成的防御阵地。9月7日的最大看点是" + H(ORANGE, "“利好落地反而全线下跌”") + "：财政部3000亿元注资落地，工行不超1000亿、农行不超1600亿，但" + H(GREEN, "42家上市银行全部收绿、中证银行指数跌1.46%") + "，工行跌1.97%、招行跌1.49%。这不是基本面变坏，而是" + H(GREEN, "埋伏资金获利了结加上资金被算力链的赚钱效应吸引走了") + "。基本面方向没变：" + H(RED, "二季度净息差1.41%仍是四年来首次单季回升") + "，" + H(RED, "42家银行上半年营收+7.4%、净利+2.96%") + "。隐患同样清楚：招行单名权重达到 " + H(ORANGE, f"{_gfp:.0f}%") + "，零售资产质量或市场风格一旦反转，回撤会全部压在它身上；宁波银行年内涨幅已经不小、估值谈不上便宜；而" + H(GREEN, "农行的持仓几乎可以忽略不计，偏偏它才是结构上最需要补齐的一环") + "。")
D["持仓分析_操作"] = ("方向已明确——" + H(RED, "优先加仓国有大行补足最大缺口") + "：农行受注资+分红提升双重催化、确定性最高，且本次回调2.16%后性价比改善，建议在" + H(CYAN, "回踩5日或10日线分批吸纳，把国有大行占比往40%推进") + "。" + H(GREEN, "招行不卖") + "、靠加仓自然稀释至30%，其ROE与股息率仍是核心底仓。" + H(ORANGE, "宁波银行估值偏高、年内涨幅大，不建议追高") + "；若坚持加城商行，额度更应给 " + H(CYAN, "江苏/杭州（股息率4.6%/4.3%更优）") + "，但城商行已接近目标、边际额度有限。总仓位控在 " + H(CYAN, "7成以内") + "，留现金等9/11 CPI与9/15-16 FOMC。")
D["持仓分析_判断"] = ("把时间轴拉到一年到一年半，" + H(RED, "工行与农行在注资叠加分红两条主线下仍有重估余地") + "，让组合逐步收敛到4:3:3是风险收益比更划算的选择；" + H(CYAN, "险资已配2.1万亿红利、仍欠配约1.9万亿") + "，长线资金对高股息的承接尚未结束。" + H(GREEN, "主要风险在美债利率反弹（10Y 4.784%、法兴提示5.5%是临界点）压制类债估值、以及风格持续偏向成长导致的相对失血") + "。落到操作上：把农行当作加仓主线，招行继续持有不加不减，宁波保持克制，江苏与杭州只做小幅摊薄，靠时间换空间，不追高、不加杠杆；单日利好兑现的下跌不改变年度级别的收息逻辑。")
# 占比对比可视化条（现状 vs 目标 4:3:3）：条形长度=占组合比重，数值用高亮 span（不带字号），整体单行注入不增报告行数
_bars = [("国有大行", _ggp, 40.0, "#00d4ff"), ("股份行", _gfp, 30.0, "#ffa657"), ("城商行", _csp, 30.0, "#3fb950")]
_bar_html = ""
for _nm, _cur, _tgt, _col in _bars:
    _d = _cur - _tgt
    _dev = H("#3fb950", "基本达标") if abs(_d) < 1.0 else (H("#ffa657", f"超配 {_d:.0f}pct") if _d > 0 else H("#00d4ff", f"欠配 {abs(_d):.0f}pct"))
    _bar_html += f'<div style="display:flex;align-items:center;gap:10px;margin:7px 0;font-size:12px;"><div style="width:60px;color:var(--text-muted);flex-shrink:0;">{_nm}</div><div style="flex:1;height:14px;background:var(--bg-hover);border-radius:7px;overflow:hidden;"><div style="width:{_cur:.1f}%;height:100%;background:{_col};border-radius:7px;opacity:0.9;"></div></div><div style="width:172px;text-align:right;color:var(--text-secondary);flex-shrink:0;">现状 {H(_col, f"{_cur:.1f}%")} · 目标 {_tgt:.0f}% → {_dev}</div></div>'
D["持仓分析_对比条"] = f'<div style="margin:4px 0 2px;padding:12px 14px;background:var(--bg-secondary);border:1px solid var(--border);border-radius:10px;"><div style="font-size:12px;color:var(--text-muted);margin-bottom:8px;">当前权重对比目标 4:3:3（条形长度即占组合比重）</div>{_bar_html}</div>'
